#!/usr/bin/env python3
"""Turns tools/filter_shaders.json (from tools/dump_filter_shaders.js) into
webgl/filter_sources.mbt: the GLSL p5.js generates for its filters."""
import json
src = json.load(open('tools/filter_shaders.json'))
prefix = {'vert': '#version 300 es\n#define WEBGL2\n#define VERTEX_SHADER\nprecision highp float;\n',
          'frag': '#version 300 es\n#define WEBGL2\n#define FRAGMENT_SHADER\nprecision highp float;\n'}
out = ['// Generated by tools/gen_filter_shaders.py from the GLSL that p5.js 2.x',
       '// (p5.strands) generates for its filters. DO NOT EDIT.', '']
for name in sorted(src):
    if name == "base":  # Template only; filters use the generated specializations.
        continue
    for kind in ('vert', 'frag'):
        text = src[name][kind]
        assert text.startswith(prefix[kind]), (name, kind)
        text = text[len(prefix[kind]):]
        out.append('///|')
        out.append(f'let filter_{name}_{kind} : String =')
        for line in text.split('\n'):
            out.append('  #|' + line)
        out.append('')
open('webgl/filter_sources.mbt', 'w').write('\n'.join(out))
print('ok', sorted(src))
